<?php
declare(strict_types=1);namespace MiniErp\Repositories;use PDO;use RuntimeException;
final readonly class FiscalOperationRepository{
 public function __construct(private PDO $pdo,private int $tenantId){}
 public function transaction(callable $work):mixed{$own=!$this->pdo->inTransaction();if($own)$this->pdo->beginTransaction();try{$r=$work();if($own)$this->pdo->commit();return $r;}catch(\Throwable $e){if($own&&$this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
 public function createOrder(array $h,array $items,int $userId):int{return $this->transaction(function()use($h,$items,$userId){$productsTotal='0.00';$normalized=[];foreach($items as $item){$p=$this->product((int)($item['produto_id']??0));$q=$this->decimal($item['quantidade']??'0',4);$price=$this->decimal($item['preco_unitario']??$p['preco'],4);if(bccomp($q,'0',4)<=0)continue;$gross=bcmul($q,$price,2);$discount=$this->decimal($item['desconto']??'0');$net=bcsub($gross,$discount,2);$productsTotal=bcadd($productsTotal,$gross,2);$normalized[]=[$p,$q,$price,$gross,$discount,$net];}if(!$normalized)throw new RuntimeException('Adicione ao menos um item válido.');$discount=$this->decimal($h['desconto_valor']??'0');$freight=$this->decimal($h['frete']??'0');$insurance=$this->decimal($h['seguro']??'0');$other=$this->decimal($h['outras_despesas']??'0');$grand=bcadd(bcsub($productsTotal,$discount,2),bcadd($freight,bcadd($insurance,$other,2),2),2);$sql='INSERT INTO fiscal_orders(tenant_id,operation_type,establishment_id,person_id,internal_code,operation_date,commercial_status,operation_nature,fiscal_model,purpose,final_consumer,presence_indicator,payment_condition,payment_method,first_due_date,notes,seller_id,carrier_id,driver_id,freight_mode,discount_amount,freight_amount,insurance_amount,other_amount,products_total,grand_total,created_by) VALUES(:tenant,:type,:establishment,:person,:code,:date,\'SAVED\',:nature,:model,:purpose,:consumer,:presence,:condition,:method,:due,:notes,:seller,:carrier,:driver,:freight_mode,:discount,:freight,:insurance,:other,:products,:grand,:created_by)';$s=$this->pdo->prepare($sql);$s->execute(['tenant'=>$this->tenantId,'type'=>strtoupper(($h['tipo']??'saida')==='entrada'?'ENTRY':'EXIT'),'establishment'=>(int)($h['establishment_id']??1),'person'=>(int)($h['cliente_id']??$h['fornecedor_id']??0),'code'=>trim((string)($h['codigo_interno']??'')),'date'=>$h['data_venda']??date('Y-m-d'),'nature'=>trim((string)($h['operation_nature']??'')),'model'=>$h['fiscal_model']??'55','purpose'=>$h['purpose']??'NORMAL','consumer'=>!empty($h['final_consumer'])?1:0,'presence'=>$h['presence_indicator']??'1','condition'=>$h['condicao_pagamento']??'','method'=>$h['payment_method']??$h['documento']??'','due'=>($h['vencimento']??'')?:null,'notes'=>$h['observacoes']??'','seller'=>(int)($h['vendedor_id']??0)?:null,'carrier'=>(int)($h['transportadora_id']??0)?:null,'driver'=>(int)($h['motorista_id']??0)?:null,'freight_mode'=>$h['freight_mode']??'9','discount'=>$discount,'freight'=>$freight,'insurance'=>$insurance,'other'=>$other,'products'=>$productsTotal,'grand'=>$grand,'created_by'=>$userId]);$id=(int)$this->pdo->lastInsertId();$is=$this->pdo->prepare('INSERT INTO fiscal_order_items(order_id,product_id,quantity,unit_price,discount_amount,gross_total,net_total) VALUES(?,?,?,?,?,?,?)');foreach($normalized as [$p,$q,$price,$gross,$disc,$net])$is->execute([$id,$p['id'],$q,$price,$disc,$gross,$net]);return $id;});}
 public function order(int $id):array{$s=$this->pdo->prepare('SELECT * FROM fiscal_orders WHERE id=? AND tenant_id=?');$s->execute([$id,$this->tenantId]);$h=$s->fetch(PDO::FETCH_ASSOC);if(!$h)throw new RuntimeException('Pedido não encontrado no tenant.');$s=$this->pdo->prepare('SELECT p.*,oi.id AS order_item_id,oi.quantity,oi.unit_price,oi.discount_amount,oi.freight_amount AS item_freight,oi.insurance_amount AS item_insurance,oi.other_amount AS item_other,oi.gross_total,oi.net_total FROM fiscal_order_items oi JOIN produtos p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$s->execute([$id]);$h['items']=$s->fetchAll(PDO::FETCH_ASSOC);return $h;}
 public function createMirror(int $orderId,int $userId,string$idempotencyKey=''):int{$lock='mini-erp:mirror:'.$this->tenantId.':'.$orderId.':'.hash('sha256',$idempotencyKey);$locked=(int)$this->pdo->query('SELECT GET_LOCK('.$this->pdo->quote($lock).',5)')->fetchColumn()===1;if(!$locked)throw new RuntimeException('MIRROR_BUSY');try{return $this->transaction(function()use($orderId,$userId,$idempotencyKey){if($idempotencyKey!==''){$s=$this->pdo->prepare("SELECT id FROM fiscal_mirrors WHERE tenant_id=? AND source_order_id=? AND JSON_UNQUOTE(JSON_EXTRACT(operation_snapshot_json,'$._idempotency_key'))=? ORDER BY id DESC LIMIT 1");$s->execute([$this->tenantId,$orderId,$idempotencyKey]);if($id=$s->fetchColumn())return(int)$id;}$order=$this->order($orderId);if($idempotencyKey!=='')$order['_idempotency_key']=$idempotencyKey;$s=$this->pdo->prepare('SELECT COALESCE(MAX(snapshot_version),0)+1 FROM fiscal_mirrors WHERE tenant_id=? AND source_order_id=? FOR UPDATE');$s->execute([$this->tenantId,$orderId]);$v=(int)$s->fetchColumn();$s=$this->pdo->prepare('INSERT INTO fiscal_mirrors(tenant_id,source_order_id,snapshot_version,operation_snapshot_json,pending_json,created_by) VALUES(?,?,?,?,?,?)');$s->execute([$this->tenantId,$orderId,$v,json_encode($order,JSON_THROW_ON_ERROR),json_encode([],JSON_THROW_ON_ERROR),$userId]);return(int)$this->pdo->lastInsertId();});}finally{$this->pdo->query('SELECT RELEASE_LOCK('.$this->pdo->quote($lock).')');}}
 public function listOrders(?string $type=null):array{$sql='SELECT o.*,COALESCE(c.nome,f.nome,\'Pessoa\') person_name,(SELECT COUNT(*) FROM fiscal_order_items i WHERE i.order_id=o.id) item_count,(SELECT COUNT(*) FROM fiscal_mirrors m WHERE m.source_order_id=o.id AND m.tenant_id=o.tenant_id) mirror_count,(SELECT MAX(d.id) FROM fiscal_documents d WHERE d.source_order_id=o.id AND d.tenant_id=o.tenant_id) document_id FROM fiscal_orders o LEFT JOIN clientes c ON c.id=o.person_id AND o.operation_type=\'EXIT\' LEFT JOIN fornecedores f ON f.id=o.person_id AND o.operation_type=\'ENTRY\' WHERE o.tenant_id=?';$params=[$this->tenantId];if($type){$sql.=' AND o.operation_type=?';$params[]=$type;}$sql.=' ORDER BY o.id DESC';$s=$this->pdo->prepare($sql);$s->execute($params);return $s->fetchAll(PDO::FETCH_ASSOC);}
 public function updateOrder(int $id,array $h,array $items):void{$this->transaction(function()use($id,$h,$items){$this->order($id);$products='0.00';$rows=[];foreach($items as $item){$p=$this->product((int)($item['produto_id']??0));$q=$this->decimal($item['quantidade']??0,4);$price=$this->decimal($item['preco_unitario']??$p['preco'],4);if(bccomp($q,'0',4)<=0)continue;$gross=bcmul($q,$price,2);$disc=$this->decimal($item['desconto']??0);$net=bcsub($gross,$disc,2);$products=bcadd($products,$gross,2);$rows[]=[$p['id'],$q,$price,$disc,$gross,$net];}if(!$rows)throw new RuntimeException('Adicione ao menos um item válido.');$discount=$this->decimal($h['desconto_valor']??0);$freight=$this->decimal($h['frete']??0);$insurance=$this->decimal($h['seguro']??0);$other=$this->decimal($h['outras_despesas']??0);$grand=bcadd(bcsub($products,$discount,2),bcadd($freight,bcadd($insurance,$other,2),2),2);$hasDoc=(int)$this->pdo->query('SELECT COUNT(*) FROM fiscal_documents WHERE tenant_id='.(int)$this->tenantId.' AND source_order_id='.(int)$id)->fetchColumn()>0;$sql='UPDATE fiscal_orders SET person_id=?,operation_date=?,operation_nature=?,fiscal_model=?,purpose=?,final_consumer=?,presence_indicator=?,payment_condition=?,payment_method=?,first_due_date=?,notes=?,seller_id=?,carrier_id=?,driver_id=?,freight_mode=?,discount_amount=?,freight_amount=?,insurance_amount=?,other_amount=?,products_total=?,grand_total=?,fiscal_status=? WHERE id=? AND tenant_id=?';$this->pdo->prepare($sql)->execute([(int)($h['cliente_id']??0),$h['data_venda']??date('Y-m-d'),$h['operation_nature']??'',$h['fiscal_model']??'55',$h['purpose']??'NORMAL',!empty($h['final_consumer'])?1:0,$h['presence_indicator']??'1',$h['condicao_pagamento']??'',$h['payment_method']??$h['documento']??'',($h['vencimento']??'')?:null,$h['observacoes']??'',(int)($h['vendedor_id']??0)?:null,(int)($h['transportadora_id']??0)?:null,(int)($h['motorista_id']??0)?:null,$h['freight_mode']??'9',$discount,$freight,$insurance,$other,$products,$grand,$hasDoc?'DOCUMENT_OUTDATED':'NOT_CREATED',$id,$this->tenantId]);$this->pdo->prepare('DELETE FROM fiscal_order_items WHERE order_id=?')->execute([$id]);$s=$this->pdo->prepare('INSERT INTO fiscal_order_items(order_id,product_id,quantity,unit_price,discount_amount,gross_total,net_total) VALUES(?,?,?,?,?,?,?)');foreach($rows as $row)$s->execute(array_merge([$id],$row));});}
 public function mirrors(int $orderId):array{$this->order($orderId);$s=$this->pdo->prepare('SELECT id,snapshot_version,created_by,created_at FROM fiscal_mirrors WHERE tenant_id=? AND source_order_id=? ORDER BY snapshot_version');$s->execute([$this->tenantId,$orderId]);return $s->fetchAll(PDO::FETCH_ASSOC);}
 public function mirror(int $id):array{$s=$this->pdo->prepare('SELECT * FROM fiscal_mirrors WHERE id=? AND tenant_id=?');$s->execute([$id,$this->tenantId]);$m=$s->fetch(PDO::FETCH_ASSOC);if(!$m)throw new RuntimeException('Espelho não encontrado no tenant.');$m['snapshot']=json_decode($m['operation_snapshot_json'],true,512,JSON_THROW_ON_ERROR);$m['pending']=json_decode($m['pending_json'],true,512,JSON_THROW_ON_ERROR);return $m;}
 public function documents(int $orderId):array{$this->order($orderId);$s=$this->pdo->prepare('SELECT id,document_version,status,pending_json,created_by,created_at FROM fiscal_documents WHERE tenant_id=? AND source_order_id=? ORDER BY document_version');$s->execute([$this->tenantId,$orderId]);return $s->fetchAll(PDO::FETCH_ASSOC);}
 public function document(int $id):array{$s=$this->pdo->prepare('SELECT * FROM fiscal_documents WHERE id=? AND tenant_id=?');$s->execute([$id,$this->tenantId]);$d=$s->fetch(PDO::FETCH_ASSOC);if(!$d)throw new RuntimeException('Documento não encontrado no tenant.');foreach(['pending_json','issuer_snapshot_json','recipient_snapshot_json','payment_snapshot_json','transport_snapshot_json','totals_json'] as $f)$d[substr($f,0,-5)]=json_decode($d[$f],true,512,JSON_THROW_ON_ERROR);$s=$this->pdo->prepare('SELECT * FROM fiscal_document_items WHERE fiscal_document_id=? ORDER BY id');$s->execute([$id]);$d['items']=$s->fetchAll(PDO::FETCH_ASSOC);return $d;}
 public function findDocumentByKey(string $key):?array{$s=$this->pdo->prepare('SELECT * FROM fiscal_documents WHERE tenant_id=? AND idempotency_key=?');$s->execute([$this->tenantId,$key]);return $s->fetch(PDO::FETCH_ASSOC)?:null;}
 public function contextualCfop(int$establishmentId,string$direction,string$originState,string$destinationState):?string{$originState=strtoupper(trim($originState));$destinationState=strtoupper(trim($destinationState));if($originState===''||$destinationState==='')return null;$scope=$originState===$destinationState?'INTERNAL':'INTERSTATE';$context=strtoupper($direction).'_'.$scope;if(!in_array($context,['ENTRY_INTERNAL','ENTRY_INTERSTATE','EXIT_INTERNAL','EXIT_INTERSTATE'],true))return null;try{$s=$this->pdo->prepare("SELECT d.cfop FROM establishment_cfop_defaults d JOIN cfops c ON CONVERT(c.codigo USING utf8mb4) COLLATE utf8mb4_unicode_ci=d.cfop COLLATE utf8mb4_unicode_ci AND c.status='ativo' WHERE d.tenant_id=? AND d.establishment_id=? AND d.operation_context=? LIMIT 1");$s->execute([$this->tenantId,$establishmentId,$context]);$cfop=(string)$s->fetchColumn();return preg_match('/^\d{4}$/',$cfop)?$cfop:null;}catch(\Throwable){return null;}}
 public function pdo():PDO{return $this->pdo;} public function tenantId():int{return $this->tenantId;}
 private function model(mixed$value):string{$model=trim((string)$value);if(!in_array($model,['55','65'],true))throw new RuntimeException('FISCAL_DOCUMENT_MODEL_UNSUPPORTED');return$model;}
 private function product(int $id):array{$s=$this->pdo->prepare('SELECT * FROM produtos WHERE id=?');$s->execute([$id]);$p=$s->fetch(PDO::FETCH_ASSOC);if(!$p)throw new RuntimeException('Produto inválido.');return $p;}
 private function decimal(mixed $v,int $scale=2):string{$v=str_replace(',','.',trim((string)$v));if(!preg_match('/^-?\d+(\.\d+)?$/',$v))$v='0';return bcadd($v,'0',$scale);}
}
